customCSS:
/* 1. Keep all navigation text uniform and slightly larger */
a.slds-container_fluid.slds-truncate,
a.slds-container_fluid.slds-truncate * {
    font-weight: 700 !important;
    font-size: 0.95rem !important;
    color: #1A1D3B !important;
}

/* Active navigation item highlight */
a.slds-container_fluid.slds-truncate.slds-is-active,
a.slds-container_fluid.slds-truncate.slds-is-active * {
    font-weight: 800 !important;
}

/* Base desktop styles for Powered by watermark */
.selfServiceUserProfileMenu::before,
div[class*="userProfile"]::before {
    content: "Powered by CloudNextGen IT Software Solutions" !important;
    position: absolute !important;
    right: 130% !important;
    top: 50% !important;
    transform: translateY(-50%) !important;
    font-size: 0.95rem !important;
    font-weight: 700 !important;
    background: linear-gradient(90deg, #1EC9C0 0%, #17A9D8 25%, #1A7FD4 50%, #3D5FC4 70%, #6B4FA8 85%, #B7C15A 100%) !important;
    -webkit-background-clip: text !important;
    background-clip: text !important;
    -webkit-text-fill-color: transparent !important;
    color: transparent !important;
    white-space: nowrap !important;
    display: block !important;
    z-index: 1 !important;
    line-height: 1 !important;
    margin-top: -1px !important;
    letter-spacing: 0.2px !important;
    pointer-events: none !important;
}

/* Mobile responsive adjustments */
@media screen and (max-width: 768px) {
    .selfServiceUserProfileMenu::before,
    div[class*="userProfile"]::before {
        content: "Powered by CloudNextGen IT Software Solutions" !important;
        right: 0 !important;
        top: 130% !important;
        transform: none !important;
        font-size: 0.70rem !important;
    }
}

@media screen and (max-width: 768px) {
    .selfServiceProfileMenuTrigger .triggerDownArrow.down-arrow {
        display: inline-block !important;
        width: 0 !important;
        height: 0 !important;
        border-top: 5px solid rgba(34, 34, 34, 0.8) !important;
        border-left: 5px solid transparent !important;
        border-right: 5px solid transparent !important;
        margin-left: 4px !important;
        vertical-align: middle !important;
    }
}

/* Hide "My Account" links from the User Profile Menu */
li.myAccount {
    display: none !important;
}
